def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    day = day_context['day']
    supply = float(day_context['supply'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    prev_bids = []
    desperate_count = 0
    rich_count = 0
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('budget', 0) >= 500:
                rich_count += 1
            if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 2:
                desperate_count += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                prev_bids.append(float(prev['bid']))

    if not alive_opponents:
        return float(min(budget, 18.0))

    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0
    max_prev = max(prev_bids) if prev_bids else 0.0

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if scarcity < 0:
        scarcity = 0.0
    if scarcity > 1:
        scarcity = 1.0

    urgency = 0.0
    if hp <= 2:
        urgency += 0.75
    elif hp <= 4:
        urgency += 0.45
    elif hp <= 6:
        urgency += 0.2

    if no_water_days >= 2:
        urgency += 0.7
    elif no_water_days >= 1:
        urgency += 0.3

    if day >= 8:
        urgency += 0.15

    pressure = 0.0
    if max_prev >= 120:
        pressure = 0.85
    elif max_prev >= 95:
        pressure = 0.65
    elif max_prev >= 70:
        pressure = 0.45
    elif max_prev > 0:
        pressure = 0.25

    if supply >= 23:
        base = 18.0
    elif supply >= 20:
        base = 28.0
    elif supply >= 17:
        base = 42.0
    else:
        base = 58.0

    if rich_count >= 2 and scarcity > 0.5 and urgency < 0.8:
        bid = 16.0
    else:
        bid = base + 18.0 * urgency + 16.0 * pressure + 10.0 * scarcity
        if desperate_count >= 2:
            bid += 8.0

    if urgency >= 1.1:
        bid = max(bid, max_prev + 3.0 if max_prev > 0 else 72.0)
    elif urgency >= 0.7 and 40.0 <= max_prev <= 95.0:
        bid = max(bid, max_prev + 2.0)

    if hp >= 7 and no_water_days == 0 and max_prev >= 110 and supply <= 18:
        bid = min(bid, 24.0)

    if budget < DAILY_SALARY:
        bid = min(bid, budget * 0.92)
    else:
        bid = min(bid, budget)

    if bid < 0:
        bid = 0.0

    return float(round(bid, 2))

